      const apFn_[playerId] = () => {
        fetch('https://api.injahow.cn/meting/?server=netease&type=playlist&id=8197566341&r=0.3385258201371981')
          .then(res => res.json())
          .then(result => {
            if (!result.length) return;
            const ap_[playerId] = new APlayer({
              container: document.getElementById('music-player-[playerId]'),
              autoplay: false,
              theme: '#1a1a1a',
              loop: 'all',
              order: 'list',
              volume: 0.5,
              lrcType: 3,
              audio: result
            });
          });
      };
      window.apFnList ? window.apFnList.push(apFn_[playerId]) : window.apFnList = [apFn_[playerId]];
      document.addEventListener("DOMContentLoaded", apFn_[playerId]);



